function renderSettingDefinitions(containerEl, items, host, app) {
  const cleanups = [];
  function renderControl(setting, name, control) {
    const current = host.getControlValue(control.key);
    const save = (value) => {
      void host.setControlValue(control.key, value);
    };
    switch (control.type) {
      case "toggle":
        setting.addToggle((t2) => t2.setValue(current).onChange(save));
        break;
      case "dropdown":
        setting.addDropdown((d) => {
          for (const [k, v] of Object.entries(control.options)) d.addOption(k, v);
          d.setValue(String(current)).onChange(save);
        });
        break;
      case "slider": {
        const fmt = control.displayFormat;
        const label = (v) => {
          if (fmt) setting.setName(`${name}: ${fmt(v)}`);
        };
        label(current);
        setting.addSlider(
          (s) => s.setLimits(control.min, control.max, control.step).setValue(current).onChange((v) => {
            save(v);
            label(v);
          })
        );
        break;
      }
      case "textarea":
        setting.addTextArea((t2) => {
          t2.setValue(current).onChange(save);
          if (control.rows) t2.inputEl.rows = control.rows;
        });
        break;
      case "folder":
        setting.addText((t2) => {
          t2.setPlaceholder(control.placeholder ?? "").setValue(current).onChange(save);
          new FolderSuggest(app, t2.inputEl);
        });
        break;
      case "number":
        setting.addText(
          (t2) => t2.setPlaceholder(control.placeholder ?? "").setValue(String(current)).onChange((v) => save(Number(v)))
        );
        break;
      case "text":
      default:
        setting.addText(
          (t2) => t2.setPlaceholder(control.placeholder ?? "").setValue(String(current)).onChange(save)
        );
        break;
    }
  }
  function renderItem(parentEl, item) {
    const visible = item.visible;
    if (visible === false || typeof visible === "function" && !visible()) return;
    if (item.type === "group" || item.type === "list") {
      const group = item;
      if (group.heading) new import_obsidian4.Setting(parentEl).setName(group.heading).setHeading();
      for (const sub of group.items ?? []) renderItem(parentEl, sub);
      return;
    }
    const def = item;
    const setting = new import_obsidian4.Setting(parentEl);
    if (def.name) setting.setName(def.name);
    if (typeof def.desc === "string") setting.setDesc(def.desc);
    if (typeof def.render === "function") {
      const cleanup = def.render(setting);
      if (typeof cleanup === "function") cleanups.push(cleanup);
      return;
    }
    if (typeof def.action === "function") {
      const action = def.action;
      setting.addButton((b) => b.setButtonText(def.name ?? "").onClick(() => action(setting.settingEl, 0)));
      return;
    }
    if (def.control) renderControl(setting, def.name ?? "", def.control);
  }
  for (const item of items) renderItem(containerEl, item);
  return () => {
    for (const c of cleanups) {
      try {
        c();
      } catch {
      }
    }
    cleanups.length = 0;
  };
}

