var MCP_CLIENTS = [
  { id: "claude-code", labelKey: "mcpClient.label.claudeCode", hint: "claude mcp add \u2026" },
  // i18n-exempt: technischer Konfig-Fragment-Bezeichner, kein Fließtext
  { id: "opencode", labelKey: "mcpClient.label.opencode", hint: "mcp-Block" },
  // i18n-exempt: technischer Konfig-Fragment-Bezeichner, kein Fließtext
  { id: "openclaw", labelKey: "mcpClient.label.openclaw", hint: "mcp.servers-Block" },
  // i18n-exempt: technischer Konfig-Fragment-Bezeichner, kein Fließtext
  { id: "generic", labelKey: "mcpClient.label.generic", hint: "mcpServers-Block" }
  // i18n-exempt: technischer Konfig-Fragment-Bezeichner, kein Fließtext
];
var SERVER_NAME = "vault-retrieval";
function buildClientSnippet(id, ctx) {
  const auth = `Bearer ${ctx.token}`;
  switch (id) {
    case "claude-code":
      return `claude mcp add --transport http ${SERVER_NAME} ${ctx.url} --header "Authorization: ${auth}"`;
    case "opencode":
      return JSON.stringify({
        mcp: { [SERVER_NAME]: { type: "remote", url: ctx.url, enabled: true, headers: { Authorization: auth } } }
      }, null, 2);
    case "openclaw":
      return JSON.stringify({
        mcp: { servers: { [SERVER_NAME]: { url: ctx.url, transport: "streamable-http", headers: { Authorization: auth } } } }
      }, null, 2);
    case "generic":
      return JSON.stringify({
        mcpServers: { [SERVER_NAME]: { type: "http", url: ctx.url, headers: { Authorization: auth } } }
      }, null, 2);
  }
}
function maskToken(token) {
  return token.length >= 5 ? `${token.slice(0, 4)}\u2026` : "\u2022\u2022\u2022\u2022";
}

// src/mcp/mcp_diagnostics.ts
function classifySelfCheck(input) {
  if (input.networkError) return "unreachable";
  if (input.status === 401) return "unauthorized";
  if (input.status === 200 && /"result"\s*:/.test(input.bodyText)) return "ok";
  return "wrong-response";
}
function mapStartError(e) {
  if (e.code === "EADDRINUSE") return { kind: "port-in-use" };
  return { kind: "other", raw: e.message ?? null };
}
function describeStartError(reason) {
  if (reason.kind === "port-in-use") return t("mcp.startError.portInUse");
  return reason.raw ?? t("mcp.startError.unknown");
}

