var VIEW_TYPE_SEARCH = "vault-rag-search";
var MIN_QUERY = 3;
var DEBOUNCE_MS = 400;
var SearchPanel = class {
  constructor(deps) {
    this.deps = deps;
    this.id = "search";
    this.icon = "search";
    this.inputEl = null;
    this.resultsEl = null;
    this.timer = null;
  }
  get label() {
    return t("panel.search.label");
  }
  mount(container) {
    this.container = container;
    const c = this.container;
    c.empty();
    const input = c.createEl("input", { cls: "vault-rag-search-input" });
    input.type = "text";
    input.placeholder = t("panel.search.placeholder");
    this.inputEl = input;
    this.resultsEl = c.createDiv({ cls: "vault-rag-search-results" });
    input.addEventListener("input", () => this.schedule(input.value ?? ""));
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") void this.runQuery(input.value ?? "");
    });
    this.renderState(t("panel.search.prompt"));
  }
  schedule(query) {
    if (this.timer !== null) window.clearTimeout(this.timer);
    this.timer = window.setTimeout(() => void this.runQuery(query), DEBOUNCE_MS);
  }
  async runQuery(query) {
    const q = query.trim();
    if (q.length < MIN_QUERY) {
      this.renderState(t("panel.search.prompt"));
      return;
    }
    this.renderResult(await this.deps.search(q));
  }
  renderResult(result) {
    if (result.kind === "offline") return this.renderState(t("panel.search.offline"));
    if (result.kind === "no-index") return this.renderState(t("panel.search.noIndex"));
    if (result.hits.length === 0) return this.renderState(t("panel.search.noHits"));
    const el = this.resultsEl;
    el.empty();
    renderHits(el, result.hits, this.deps.openPath);
  }
  renderState(text) {
    const el = this.resultsEl;
    el.empty();
    el.createDiv({ cls: "vault-rag-search-state", text });
  }
  destroy() {
    if (this.timer !== null) window.clearTimeout(this.timer);
  }
};

// src/context_source.ts
async function buildContext(paths, deps) {
  const perNote = paths.length > 0 ? Math.floor(deps.budget / paths.length) : deps.budget;
  const blocks = [];
  const sources = [];
  for (const p of paths) {
    let text;
    try {
      text = await deps.read(p);
    } catch {
      continue;
    }
    blocks.push(`## ${p}
${text.slice(0, perNote)}`);
    sources.push(p);
  }
  return { text: blocks.join("\n\n"), sources };
}

